const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

test("finding 9: Later writes later", async ({ page }) => {
  await page.goto("index.html");
  await page.locator("#later").click();
  await expect(page.locator("#out")).toHaveText("later");
});

